using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Pagination;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Customers;

namespace BARANG.Core.Application.Customers;

public sealed class CustomerAdministration(ICustomerStore store,ITransactionExecutor transactions,ICompanyContext company,IAuditWriter audit,TimeProvider time):ICustomerAdministration
{
    public Task<Result<CustomerView>> CreateAsync(CustomerDataCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{Guid companyId=company.RequireCompanyId();Result<Customer> created=Customer.Create(Guid.NewGuid(),companyId,c.CustomerCode,c.CustomerType,c.DisplayName,c.FirstName,c.LastName,c.LegalName,c.NationalId,c.RegistrationNo,c.TaxId,c.PrimaryMobile,c.PrimaryPhone,c.PrimaryEmail,c.Notes,time.GetUtcNow());if(created.IsFailure)return Result.Failure<CustomerView>(created.Error);if(await store.CodeExistsAsync(created.Value.CustomerCode,token))return Result.Failure<CustomerView>(CustomerErrors.DuplicateCode);if(await store.IdentifierExistsAsync(created.Value.NationalId,created.Value.RegistrationNo,null,token))return Result.Failure<CustomerView>(CustomerErrors.DuplicateIdentifier);store.Add(created.Value);Write(AuditActions.CustomerCreated,"customer",created.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerCode",created.Value.CustomerCode},{"customerType",created.Value.CustomerType.ToString()}});return Result.Success(View(created.Value));},ct);
    public Task<Result<CustomerView>> GetAsync(Guid id,CancellationToken ct)=>Read(async token=>Map(await store.FindAsync(id,token),View,CustomerErrors.NotFound),ct);
    public Task<Result<CustomerView>> GetByCodeAsync(string code,CancellationToken ct)=>Read(async token=>{string? normalized=CustomerText.Code(code);return normalized is null?Result.Failure<CustomerView>(CustomerErrors.InvalidCode):Map(await store.FindByCodeAsync(normalized,token),View,CustomerErrors.NotFound);},ct);
    public Task<Result<PagedResult<CustomerView>>> SearchAsync(CustomerQuery query,CancellationToken ct)=>Read(async token=>{try{PagedResult<Customer> page=await store.SearchAsync(query,token);return Result.Success(new PagedResult<CustomerView>(page.Items.Select(View),page.PageNumber,page.PageSize,page.TotalCount));}catch(ArgumentOutOfRangeException){return Result.Failure<PagedResult<CustomerView>>(Error.Validation("customer.invalid_pagination"));}},ct);
    public Task<Result<IReadOnlyList<CustomerOptionView>>> OptionsAsync(string? search,bool activeOnly,int limit,CancellationToken ct)=>Read(async token=>limit is <1 or >100?Result.Failure<IReadOnlyList<CustomerOptionView>>(Error.Validation("customer.invalid_pagination")):Result.Success<IReadOnlyList<CustomerOptionView>>((await store.OptionsAsync(search,activeOnly,limit,token)).Select(x=>new CustomerOptionView(x.Id,x.CustomerCode,x.DisplayName,x.CustomerType,x.PrimaryMobile)).ToArray()),ct);
    public Task<Result<CustomerView>> UpdateAsync(Guid id,CustomerUpdateCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{company.RequireCompanyId();Customer? x=await store.FindAsync(id,token);if(x is null)return Result.Failure<CustomerView>(CustomerErrors.NotFound);if(x.Version!=c.Version)return Result.Failure<CustomerView>(CustomerErrors.Concurrency);string old=x.DisplayName;bool oldHasEmail=x.PrimaryEmail is not null;Result changed=x.Update(c.DisplayName,c.FirstName,c.LastName,c.LegalName,c.NationalId,c.RegistrationNo,c.TaxId,c.PrimaryMobile,c.PrimaryPhone,c.PrimaryEmail,c.Notes,time.GetUtcNow());if(changed.IsFailure)return Result.Failure<CustomerView>(changed.Error);if(await store.IdentifierExistsAsync(x.NationalId,x.RegistrationNo,x.Id,token))return Result.Failure<CustomerView>(CustomerErrors.DuplicateIdentifier);Dictionary<string,AuditValueChange> changes=[];Add(changes,"displayName",old,x.DisplayName);Add(changes,"hasPrimaryEmail",oldHasEmail,x.PrimaryEmail is not null);Write(AuditActions.CustomerUpdated,"customer",id,AuditChangeKind.Modified,changes:changes);return Result.Success(View(x));},ct);
    public Task<Result<CustomerView>> SetActiveAsync(Guid id,bool active,long version,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{company.RequireCompanyId();Customer? x=await store.FindAsync(id,token);if(x is null)return Result.Failure<CustomerView>(CustomerErrors.NotFound);if(x.Version!=version)return Result.Failure<CustomerView>(CustomerErrors.Concurrency);bool old=x.IsActive;x.SetActive(active,time.GetUtcNow());Dictionary<string,AuditValueChange> changes=[];Add(changes,"isActive",old,x.IsActive);Write(active?AuditActions.CustomerActivated:AuditActions.CustomerDeactivated,"customer",id,AuditChangeKind.Modified,changes:changes);return Result.Success(View(x));},ct);
    public Task<Result<CustomerContactView>> AddContactAsync(Guid customerId,ContactCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{Customer? owner=await Owner(customerId,token);if(owner is null)return Result.Failure<CustomerContactView>(CustomerErrors.NotFound);if(c.IsPrimary&&await store.OtherPrimaryContactExistsAsync(customerId,null,token))return Result.Failure<CustomerContactView>(CustomerErrors.PrimaryConflict);Result<CustomerContact> created=CustomerContact.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.ContactTypeCode,c.Name,c.Mobile,c.Phone,c.Email,c.JobTitle,c.IsPrimary,c.DisplayOrder,time.GetUtcNow());if(created.IsFailure)return Result.Failure<CustomerContactView>(created.Error);store.Add(created.Value);Write(AuditActions.CustomerContactCreated,"customer_contact",created.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerId",customerId},{"contactType",created.Value.ContactTypeCode},{"isPrimary",created.Value.IsPrimary}});return Result.Success(ContactView(created.Value));},ct);
    public Task<Result<IReadOnlyList<CustomerContactView>>> ListContactsAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>Read(async token=>await store.FindAsync(customerId,token) is null?Result.Failure<IReadOnlyList<CustomerContactView>>(CustomerErrors.NotFound):Result.Success<IReadOnlyList<CustomerContactView>>((await store.ListContactsAsync(customerId,activeOnly,token)).Select(ContactView).ToArray()),ct);
    public Task<Result<CustomerContactView>> UpdateContactAsync(Guid customerId,Guid id,ContactCommand c,CancellationToken ct)=>ChangeContact(customerId,id,c.Version,async(x,token)=>{if(c.IsPrimary&&!x.IsPrimary&&await store.OtherPrimaryContactExistsAsync(customerId,id,token))return Result.Failure(CustomerErrors.PrimaryConflict);return x.Update(c.ContactTypeCode,c.Name,c.Mobile,c.Phone,c.Email,c.JobTitle,c.IsPrimary,c.DisplayOrder,time.GetUtcNow());},AuditActions.CustomerContactUpdated,ct);
    public Task<Result<CustomerContactView>> SetContactActiveAsync(Guid customerId,Guid id,bool active,long version,CancellationToken ct)=>ChangeContact(customerId,id,version,(x,_)=>{x.SetActive(active,time.GetUtcNow());return Task.FromResult(Result.Success());},active?AuditActions.CustomerContactActivated:AuditActions.CustomerContactDeactivated,ct);
    public Task<Result<CustomerAddressView>> AddAddressAsync(Guid customerId,AddressCommand c,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{Customer? owner=await Owner(customerId,token);if(owner is null)return Result.Failure<CustomerAddressView>(CustomerErrors.NotFound);if(c.IsPrimary&&await store.OtherPrimaryAddressExistsAsync(customerId,null,token))return Result.Failure<CustomerAddressView>(CustomerErrors.PrimaryConflict);Result<CustomerAddress> created=CustomerAddress.Create(Guid.NewGuid(),customerId,owner.CompanyId,c.AddressTypeCode,c.Title,c.CountryCode,c.Province,c.City,c.District,c.AddressLine1,c.AddressLine2,c.PostalCode,c.RecipientName,c.RecipientPhone,c.IsPrimary,c.DisplayOrder,time.GetUtcNow());if(created.IsFailure)return Result.Failure<CustomerAddressView>(created.Error);store.Add(created.Value);Write(AuditActions.CustomerAddressCreated,"customer_address",created.Value.Id,AuditChangeKind.Added,new Dictionary<string,object?>{{"customerId",customerId},{"addressType",created.Value.AddressTypeCode},{"isPrimary",created.Value.IsPrimary}});return Result.Success(AddressView(created.Value));},ct);
    public Task<Result<IReadOnlyList<CustomerAddressView>>> ListAddressesAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>Read(async token=>await store.FindAsync(customerId,token) is null?Result.Failure<IReadOnlyList<CustomerAddressView>>(CustomerErrors.NotFound):Result.Success<IReadOnlyList<CustomerAddressView>>((await store.ListAddressesAsync(customerId,activeOnly,token)).Select(AddressView).ToArray()),ct);
    public Task<Result<CustomerAddressView>> UpdateAddressAsync(Guid customerId,Guid id,AddressCommand c,CancellationToken ct)=>ChangeAddress(customerId,id,c.Version,async(x,token)=>{if(c.IsPrimary&&!x.IsPrimary&&await store.OtherPrimaryAddressExistsAsync(customerId,id,token))return Result.Failure(CustomerErrors.PrimaryConflict);return x.Update(c.AddressTypeCode,c.Title,c.CountryCode,c.Province,c.City,c.District,c.AddressLine1,c.AddressLine2,c.PostalCode,c.RecipientName,c.RecipientPhone,c.IsPrimary,c.DisplayOrder,time.GetUtcNow());},AuditActions.CustomerAddressUpdated,ct);
    public Task<Result<CustomerAddressView>> SetAddressActiveAsync(Guid customerId,Guid id,bool active,long version,CancellationToken ct)=>ChangeAddress(customerId,id,version,(x,_)=>{x.SetActive(active,time.GetUtcNow());return Task.FromResult(Result.Success());},active?AuditActions.CustomerAddressActivated:AuditActions.CustomerAddressDeactivated,ct);
    private Task<Result<CustomerContactView>> ChangeContact(Guid customerId,Guid id,long version,Func<CustomerContact,CancellationToken,Task<Result>> operation,string action,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{company.RequireCompanyId();CustomerContact? x=await store.FindContactAsync(customerId,id,token);if(x is null)return Result.Failure<CustomerContactView>(CustomerErrors.ContactNotFound);if(x.Version!=version)return Result.Failure<CustomerContactView>(CustomerErrors.Concurrency);var old=(x.ContactTypeCode,x.IsPrimary,x.IsActive,x.DisplayOrder);Result changed=await operation(x,token);if(changed.IsFailure)return Result.Failure<CustomerContactView>(changed.Error);Dictionary<string,AuditValueChange> changes=[];Add(changes,"contactType",old.ContactTypeCode,x.ContactTypeCode);Add(changes,"isPrimary",old.IsPrimary,x.IsPrimary);Add(changes,"isActive",old.IsActive,x.IsActive);Add(changes,"displayOrder",old.DisplayOrder,x.DisplayOrder);Write(action,"customer_contact",id,AuditChangeKind.Modified,changes:changes);return Result.Success(ContactView(x));},ct);
    private Task<Result<CustomerAddressView>> ChangeAddress(Guid customerId,Guid id,long version,Func<CustomerAddress,CancellationToken,Task<Result>> operation,string action,CancellationToken ct)=>transactions.ExecuteAsync(async token=>{company.RequireCompanyId();CustomerAddress? x=await store.FindAddressAsync(customerId,id,token);if(x is null)return Result.Failure<CustomerAddressView>(CustomerErrors.AddressNotFound);if(x.Version!=version)return Result.Failure<CustomerAddressView>(CustomerErrors.Concurrency);var old=(x.AddressTypeCode,x.Title,x.IsPrimary,x.IsActive,x.DisplayOrder);Result changed=await operation(x,token);if(changed.IsFailure)return Result.Failure<CustomerAddressView>(changed.Error);Dictionary<string,AuditValueChange> changes=[];Add(changes,"addressType",old.AddressTypeCode,x.AddressTypeCode);Add(changes,"title",old.Title,x.Title);Add(changes,"isPrimary",old.IsPrimary,x.IsPrimary);Add(changes,"isActive",old.IsActive,x.IsActive);Add(changes,"displayOrder",old.DisplayOrder,x.DisplayOrder);Write(action,"customer_address",id,AuditChangeKind.Modified,changes:changes);return Result.Success(AddressView(x));},ct);
    private Task<Result<T>> Read<T>(Func<CancellationToken,Task<Result<T>>> op,CancellationToken ct){company.RequireCompanyId();return transactions.ExecuteAsync(op,ct);} private async Task<Customer?> Owner(Guid id,CancellationToken ct){company.RequireCompanyId();return await store.FindAsync(id,ct);}
    private void Write(string action,string entity,Guid id,AuditChangeKind kind,IReadOnlyDictionary<string,object?>? metadata=null,IReadOnlyDictionary<string,AuditValueChange>? changes=null)=>audit.Write(new(action,entity,id.ToString(),CompanyId:company.RequireCompanyId(),ChangeKind:kind,Metadata:metadata,Changes:changes)); private static void Add<T>(Dictionary<string,AuditValueChange>d,string key,T old,T current){if(!EqualityComparer<T>.Default.Equals(old,current))d[key]=new(old,current);} private static Result<TV> Map<TE,TV>(TE? x,Func<TE,TV> map,Error error)where TE:class=>x is null?Result.Failure<TV>(error):Result.Success(map(x));
    private static CustomerView View(Customer x)=>new(x.Id,x.CompanyId,x.CustomerCode,x.CustomerType,x.DisplayName,x.FirstName,x.LastName,x.LegalName,x.NationalId,x.RegistrationNo,x.TaxId,x.PrimaryMobile,x.PrimaryPhone,x.PrimaryEmail,x.IsActive,x.Notes,x.CreatedAtUtc,x.UpdatedAtUtc,x.Version);
    private static CustomerContactView ContactView(CustomerContact x)=>new(x.Id,x.CustomerId,x.ContactTypeCode,x.Name,x.Mobile,x.Phone,x.Email,x.JobTitle,x.IsPrimary,x.IsActive,x.DisplayOrder,x.Version);
    private static CustomerAddressView AddressView(CustomerAddress x)=>new(x.Id,x.CustomerId,x.AddressTypeCode,x.Title,x.CountryCode,x.Province,x.City,x.District,x.AddressLine1,x.AddressLine2,x.PostalCode,x.RecipientName,x.RecipientPhone,x.IsPrimary,x.IsActive,x.DisplayOrder,x.Version);
}
